t.script:
                odoo.define('kw_email_validation_web.validate_form', function (require) {
                    'use strict';

                    var core = require('web.core');
                    var ajax = require('web.ajax');
                    var _t = core._t;

                    $(document).ready(function() {
                        // Handle "Validate one by one" button
                        $('#validate_single').click(function() {
                            var emails = $('#emails').val().split('\n').filter(function(email) {
                                return email.trim() !== '';
                            });

                            if (emails.length === 0) {
                                alert(_t('Enter at least one email address'));
                                return;
                            }

                            var validator_id = $('#validator_id').val();

                            // Clear previous results
                            $('#results_body').empty();
                            $('#validation_results').show();

                            // Sequential validation of each address
                            var processEmails = function(index) {
                                if (index >= emails.length) {
                                    return; // All addresses processed
                                }

                                var email = emails[index].trim();
                                if (!email) {
                                    processEmails(index + 1);
                                    return;
                                }

                                // Add row with loading indicator
                                var row_id = 'email_row_' + index;
                                $('#results_body').append(
                                    '
' +
                                    '' + email + '' +
                                    ' Checking...' +
                                    ''
                                );

                                // Send validation request
                                ajax.jsonRpc('/email_validation/validate_ajax', 'call', {
                                    'email': email,
                                    'validator_id': validator_id
                                }).then(function(result) {
                                    // Update row with result
                                    var status_class = '';
                                    var status_text = '';

                                    if (result.error) {
                                        status_class = 'text-danger';
                                        status_text = result.error;
                                    } else {
                                        if (result.state === 'valid') {
                                            status_class = 'text-success';
                                            status_text = 'Valid';
                                        } else if (result.state === 'invalid') {
                                            status_class = 'text-danger';
                                            status_text = 'Invalid';
                                        } else {
                                            status_class = 'text-warning';
                                            status_text = 'Pending';
                                        }
                                    }

                                    $('#' + row_id).html(
                                        '' + email + '' +
                                        '' + status_text + '' +
                                        '' + (result.message || '') + ''
                                    );

                                    // Move to next address
                                    processEmails(index + 1);
                                }).guardedCatch(function(error) {
                                    $('#' + row_id).html(
                                        '' + email + '' +
                                        'Error' +
                                        'Failed to validate address'
                                    );

                                    // Move to next address
                                    processEmails(index + 1);
                                });
                            };

                            // Start processing from the first address
                            processEmails(0);
                        });
                    });
                });
